test('ordinary producer reserves voice before started receipts and releases it before local rendering',async t=>{const f=fixture(t),phases=[];let active=null;const workstations={run:async(station,job,fn)=>{assert.equal(active,null);assert.equal(job,f.config.job.id);active=station;phases.push(station);try{return await fn()}finally{active=null}}};await runPrivateReviewProducer(f.config,{root:f.root,workstations,probe:f.probe,voiceGenerate:async args=>{assert.equal(active,'voice');return f.voiceGenerate(args)},command:async(...args)=>{assert.equal(active,'render');return f.command(...args)}});assert.deepEqual(phases,['preparation','voice','render']);});

test('render waiting retains exact complete ordinary source audio and next pass never calls speech again',async t=>{const f=fixture(t);let voices=0,error;const options={root:f.root,command:f.command,probe:f.probe,voiceGenerate:async args=>{voices++;return f.voiceGenerate(args)}};try{await runPrivateReviewProducer(f.config,{...options,workstations:{run:async(station,_job,fn)=>{if(station==='render')throw Object.assign(Error('SYNTHETIC render waiting budget'),{code:'PRODUCTION_STATION_BUDGET_DEFERRED',station});return fn()}}})}catch(e){error=e}assert.equal(error.code,'PRODUCTION_STATION_BUDGET_DEFERRED');assert.equal(error.audio_saved,true);assert.match(error.workstation_resume.file,/workstation-wait-[a-f0-9]{64}\.json$/);assert.equal(voices,2);const result=await runPrivateReviewProducer(f.config,{...options,voiceGenerate:()=>{throw Error('must not repeat saved speech')},workstations:{run:async(station,_job,fn)=>{assert.notEqual(station,'voice');return fn()}}});assert.equal(result.audio_generated,true);assert.equal(voices,2);});

