 const workstations={run:async(station,_job,fn)=>{if(station===defer)throw Object.assign(Error('SYNTHETIC stage wait'),{code:'PRODUCTION_STATION_BUDGET_DEFERRED',station});return fn()}},command=async(exe,args)=>{if(exe===process.execPath){const dest=path.join(path.dirname(args[0]),'rendered');fs.mkdirSync(dest);fs.writeFileSync(path.join(dest,'full-review.mp4'),'SYNTHETIC final complete video');return{out:'',error:'',exit_code:0}}return f.command(exe,args)},probe=async file=>file.endsWith('full-review.mp4')?{format:{duration:String(frames/30)},streams:[{codec_type:'video',width:1080,height:1920,nb_frames:String(frames)},{codec_type:'audio'}]}:f.probe(file),prepareRender=async args=>{frames=args.project.body.frames+120;return syntheticPrepared(args)};
