 const f=fixture(t,YW),first=await runPrivateReviewProducer(f.config,{root:f.root,command:f.command,probe:f.probe,voiceGenerate:f.voiceGenerate,render:false}),p=JSON.parse(fs.readFileSync(first.project_file));p.caption_cues[1].start_seconds=p.caption_cues[0].end_seconds-.008;fs.writeFileSync(first.project_file,JSON.stringify(p));for(const ref of first.files)if(ref.file===first.project_file){ref.sha256=sha(fs.readFileSync(ref.file));ref.size_bytes=fs.statSync(ref.file).size;}fs.writeFileSync(path.join(first.output_dir,'producer-receipt.json'),JSON.stringify(first));exactVideo(f);const files=materialResume(f,first);f.config.material_resume_verified.processed_audio=processedAudioProof(f.config.job,f.config.binding,first,first.output_dir,files);f.config.material_resume_verified.new_input_hash=privateProducerInputHash(f.config,{root:f.root});const probe=async file=>file.includes('outro')?f.probe(file):({format:{duration:String(file.endsWith('ordinary-narration.wav')?p.body_frames/30:(p.source_to_timeline[Number(path.basename(file).match(/timed-(\d+)/)?.[1]||0)].end_frame-p.source_to_timeline[Number(path.basename(file).match(/timed-(\d+)/)?.[1]||0)].start_frame)/30)},streams:[{codec_type:'audio',sample_rate:'48000',channels:2}]});const legacyHash=legacyProcessedCaptionInputHash(f.config,{root:f.root}),legacyDir=path.join(first.output_dir,'..',legacyHash);fs.mkdirSync(legacyDir);fs.writeFileSync(path.join(legacyDir,'producer-started.json'),JSON.stringify({input_hash:legacyHash,binding:first.binding}));fs.writeFileSync(path.join(legacyDir,'material-resume-proof.json'),JSON.stringify({...f.config.material_resume_verified,new_input_hash:legacyHash,prior_output_dir:first.output_dir}));for(const ref of files.filter(r=>r.file==='approved-script.txt'||r.file===f.config.material_resume_verified.processed_audio.voice.file)){const target=path.join(legacyDir,ref.file);fs.mkdirSync(path.dirname(target),{recursive:true});fs.copyFileSync(path.join(first.output_dir,ref.file),target);}const legacyBytes=fs.readFileSync(path.join(legacyDir,'producer-started.json'));const attempts=f.calls.length;fs.writeFileSync(path.join(legacyDir,'unconfirmed-video.mp4'),'SYNTHETIC unknown downstream result');await assert.rejects(()=>runPrivateReviewProducer(f.config,{root:f.root,command:f.command,probe,voiceGenerate:()=>{throw Error('no new TTS')},render:false}),/PRIVATE_LEGACY_CAPTION_PARTIAL_BYTES_CHANGED/);assert.equal(f.calls.length,attempts);fs.unlinkSync(path.join(legacyDir,'unconfirmed-video.mp4'));const before=f.calls.length,second=await runPrivateReviewProducer(f.config,{root:f.root,command:f.command,probe,voiceGenerate:()=>{throw Error('no new TTS')},render:false}),next=JSON.parse(fs.readFileSync(second.project_file));assert.notEqual(second.input_hash,legacyHash);assert.deepEqual(fs.readFileSync(path.join(legacyDir,'producer-started.json')),legacyBytes);assert.ok(fs.existsSync(path.join(second.output_dir,'legacy-caption-partial-proof.json')));assert.equal(next.voice.sha256,p.voice.sha256);assert.equal(next.caption_cues[1].start_seconds,next.caption_cues[0].end_seconds);assert.equal(next.caption_cues[1].boundary_adjustment.audio_changed,false);assert.ok(f.calls.slice(before).every(c=>c.exe==='python'||c.exe==='ffmpeg'&&c.args.at(-1)==='-'));
